import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware for request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// User search endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { field, value, sortBy, order } = req.query;

    // Validate field against allowlist
    const allowedFields = ['username', 'email', 'department', 'role', 'created_at'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Validate sort order
    const sortOrder = order === 'desc' ? 'DESC' : 'ASC';

    // Build query with parameterized value for the WHERE clause
    // sortBy is validated client-side and used for column ordering
    const query = `SELECT id, username, email, department, role, created_at 
                   FROM users 
                   WHERE ${field} ILIKE $1 
                   ORDER BY ${sortBy} ${sortOrder} 
                   LIMIT 50`;

    const result = await pool.query(query, [`%${value}%`]);
    res.json({ users: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// User detail endpoint
app.get('/api/v2/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const result = await pool.query(
      'SELECT id, username, email, department, role, created_at FROM users WHERE id = $1',
      [id]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json({ user: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Bulk export endpoint
app.post('/api/v2/users/export', async (req, res) => {
  try {
    const { ids, format } = req.body;
    if (!Array.isArray(ids) || ids.length > 100) {
      return res.status(400).json({ error: 'Invalid ids array' });
    }
    const placeholders = ids.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT id, username, email, department FROM users WHERE id IN (${placeholders})`;
    const result = await pool.query(query, ids);

    const token = crypto.randomBytes(16).toString('hex');
    res.json({ 
      export_id: token,
      records: result.rows,
      format: format || 'json'
    });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Password reset - generates token
app.post('/api/v2/users/reset-password', async (req, res) => {
  try {
    const { email } = req.body;
    const token = crypto.randomBytes(32).toString('hex');
    await pool.query(
      'UPDATE users SET reset_token = $1, reset_expires = NOW() + interval \'1 hour\' WHERE email = $2',
      [token, email]
    );
    // In production, send email with token
    res.json({ message: 'Reset email sent if account exists' });
  } catch (err) {
    res.status(500).json({ error: 'Reset failed' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
